1	use std::path::{Path, PathBuf};
2	
3	use callisto_model::vcs::{GitAccess, VcsError};
4	use callisto_model::CommandRunner;
5	
6	use crate::locate::membership::{parse_error, read_root_manifest};
7	use crate::locate::LocateError;
8	
9	/// Finds the root between `start` and its Git toplevel (never above it): the nearest workspace marker (a
10	/// `callisto.toml` counts), else the outermost package manifest so vendored packages can't shadow it.
11	///
12	/// The toplevel comes from `git rev-parse --show-toplevel` (via `runner`), not a hand-rolled
13	/// walk for a `.git` entry -- `git` alone honors `GIT_DIR`/`GIT_WORK_TREE`/
14	/// `GIT_CEILING_DIRECTORIES` the way every other Git-aware tool does.
15	pub fn find_workspace_root(start: &Path, runner: &dyn CommandRunner) -> Result<PathBuf, LocateError> {
16	    let canonical = dunce::canonicalize(start).unwrap_or_else(|_| start.to_path_buf());
17	    let toplevel = GitAccess::new(&canonical, runner).toplevel().map_err(|e| match &e {
18	        VcsError::Git(message) if message.to_lowercase().contains("not a git repository") => {
19	            LocateError::NotAGitRepository {
20	                start: start.to_path_buf(),
21	            }
22	        }
23	        _ => LocateError::from(e),
24	    })?;
25	    let range = || canonical.ancestors().take_while(|dir| dir.starts_with(&toplevel));
26	    for dir in range() {
27	        if is_workspace_root(dir)? {
28	            return Ok(dir.to_path_buf());
29	        }
30	    }
31	    let mut outermost = None;
32	    for dir in range() {
33	        if is_package_root(dir)? {
34	            outermost = Some(dir);
35	        }
36	    }
37	    outermost
38	        .map(Path::to_path_buf)
39	        .ok_or_else(|| LocateError::WorkspaceRootNotFound {
40	            start: start.to_path_buf(),
41	            toplevel: toplevel.clone(),
42	        })
43	}
44	
45	/// Loads `dir/Cargo.toml` as a TOML document, or `None` if it does not exist. A manifest that cannot be read or
46	/// parsed is an error: skipping it would let the search settle on a different root.
47	fn cargo_document(dir: &Path) -> Result<Option<toml_edit::DocumentMut>, LocateError> {
48	    let path = dir.join("Cargo.toml");
49	    read_root_manifest(&path)?
50	        .map(|content| {
51	            content
52	                .parse::<toml_edit::DocumentMut>()
53	                .map_err(|error| parse_error(&path, error.to_string()))
54	        })
55	        .transpose()
56	}
57	
58	fn path_exists(path: &Path) -> Result<bool, LocateError> {
59	    callisto_model::strict_fs::exists(path).map_err(|error| LocateError::ManifestReadError {
60	        path: path.to_path_buf(),
61	        message: error.to_string(),
62	    })
63	}
64	
65	/// A single-package repository root: `Cargo.toml` with `[package]`, `package.json`, or `pyproject.toml`.
66	fn is_package_root(dir: &Path) -> Result<bool, LocateError> {
67	    // Parsed, so a comment that mentions the name does not count; any spelling of the table does.
68	    if cargo_document(dir)?.is_some_and(|doc| doc.get("package").is_some_and(toml_edit::Item::is_table_like)) {
69	        return Ok(true);
70	    }
71	    Ok(path_exists(&dir.join("package.json"))? || path_exists(&dir.join("pyproject.toml"))?)
72	}
73	
74	fn is_workspace_root(dir: &Path) -> Result<bool, LocateError> {
75	    if cargo_document(dir)?.is_some_and(|doc| callisto_manifests::declares_workspace(&doc)) {
76	        return Ok(true);
77	    }
78	
79	    let pkg_json = dir.join("package.json");
80	    if let Some(content) = read_root_manifest(&pkg_json)? {
81	        let value = serde_json::from_str::<serde_json::Value>(&content)
82	            .map_err(|error| parse_error(&pkg_json, error.to_string()))?;
83	        if value.get("workspaces").is_some() {
84	            return Ok(true);
