                        message: e.to_string(),
                    })?;
                Ok(CommandOutput {
                    exit_code: output.status.code(),
                    stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                    stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
                })
            }
        }

        let dir = tempfile::tempdir().unwrap();
        let root = dunce::canonicalize(dir.path()).unwrap();
        assert!(
            std::process::Command::new("git")
                .args(["init", "-q"])
                .current_dir(&root)
                .status()
                .unwrap()
                .success(),
            "git init must succeed for this test to be meaningful"
        );
        write(&root, "Cargo.toml", CRATE);
        write(&root, "src/deep/file.txt", "");

        assert_eq!(
            find_workspace_root(&root.join("src/deep"), &RealGitRunner).unwrap(),
            root
        );
    }

    // A comment merely mentioning "[workspace]" must not be text-matched as a real table.
    #[test]
    fn a_commented_out_workspace_mention_does_not_count_as_a_workspace_root() {
        let (_dir, root) = repo();
        write(&root, "Cargo.toml", "[workspace]\nmembers = [\"crates/*\"]\n");
        write(
            &root,
            "crates/a/Cargo.toml",
            "[package]\nname = \"a\"\nversion = \"1.0.0\"\n# not a workspace root; see [workspace] in ../../Cargo.toml\n",
        );
        assert_eq!(find(&root.join("crates/a")).unwrap(), root);
    }

    // Cargo reads a workspace table however it is written, so root detection does too.
    #[test]
    fn a_workspace_table_in_any_spelling_is_a_workspace_root() {
        for (spelling, manifest) in [
            ("header", "[workspace]\nmembers = [\"a\"]\n"),
            ("inline", "workspace = { members = [\"a\"] }\n"),
            ("dotted", "workspace.members = [\"a\"]\n"),
            ("sub-table only", "[workspace.package]\nedition = \"2021\"\n"),
        ] {
            let dir = tempfile::tempdir().unwrap();
            write(dir.path(), "Cargo.toml", manifest);
            assert!(is_workspace_root(dir.path()).unwrap(), "{spelling}");
        }
    }

    #[test]
    fn a_package_table_in_any_spelling_is_a_package_root() {
        for (spelling, manifest) in [
            ("header", "[package]\nname = \"a\"\n"),
            ("inline", "package = { name = \"a\", version = \"1.0.0\" }\n"),
            ("dotted", "package.name = \"a\"\n"),
        ] {
            let dir = tempfile::tempdir().unwrap();
            write(dir.path(), "Cargo.toml", manifest);
            assert!(is_package_root(dir.path()).unwrap(), "{spelling}");
        }
    }

    #[test]
    fn a_cargo_toml_without_package_or_workspace_is_not_a_root() {
        let (_dir, root) = repo();
        write(&root, "Cargo.toml", "[dependencies]\n");
        assert!(matches!(find(&root), Err(LocateError::WorkspaceRootNotFound { .. })));
    }
}

