208	/// Describes where an ecosystem's workspace-membership table lives inside
209	/// its root manifest, so [`read_membership`] can walk to it generically
210	/// instead of each ecosystem hand-rolling the same members/exclude/
211	/// hybrid-root logic around a different table path.
212	pub(crate) struct MembershipSpec {
213	    /// The root manifest's file name, e.g. `Cargo.toml`.
214	    manifest_file_name: &'static str,
215	    /// Nested table keys leading to the workspace table, walked in order
216	    /// from the document root, e.g. `["workspace"]` for Cargo or
217	    /// `["tool", "uv", "workspace"]` for uv-based Python.
218	    table_path: &'static [&'static str],
219	    /// Top-level key whose co-presence with the workspace table marks a
220	    /// hybrid root, e.g. `"package"` for Cargo or `"project"` for Python.
221	    owner_key: &'static str,
222	}
