236	/// Reads the workspace membership declared by the root manifest.
237	///
238	/// A missing manifest, or one with no workspace table or no `members` key, restricts nothing. A manifest that cannot be
239	/// read or parsed, or whose `members`/`exclude` is not an array of valid globs, is an error naming the file: guessing
240	/// "every directory" there would turn vendored copies and excluded crates into releasable packages.
241	pub(crate) fn read_membership(root: &Path, spec: &MembershipSpec) -> Result<Membership, LocateError> {
242	    let path = root.join(spec.manifest_file_name);
243	    let Some(content) = read_root_manifest(&path)? else {
244	        return Ok(Membership::unrestricted());
245	    };
246	    let doc = content
247	        .parse::<toml_edit::DocumentMut>()
248	        .map_err(|error| parse_error(&path, error.to_string()))?;
249	
250	    let mut cursor: Option<&toml_edit::Item> = doc.get(spec.table_path[0]);
251	    for key in &spec.table_path[1..] {
252	        cursor = cursor.and_then(|c| c.get(*key));
253	    }
254	
255	    let hybrid_root = doc.get(spec.owner_key).is_some() && cursor.is_some();
256	    let Some(workspace) = cursor else {
257	        return Ok(Membership {
258	            members: None,
259	            exclude: NegatableGlobSet::empty(),
260	            hybrid_root,
261	            declared: false,
262	        });
263	    };
264	    let table = spec.table_path.join(".");
265	    if workspace.as_table_like().is_none() {
266	        return Err(invalid_membership(&path, format!("`{table}` must be a table")));
267	    }
268	    let globs = |key: &str| -> Result<Option<NegatableGlobSet>, LocateError> {
269	        let Some(item) = workspace.get(key) else {
270	            return Ok(None);
271	        };
272	        let full_key = format!("{table}.{key}");
273	        let entries = parse_toml_string_array(item)
274	            .ok_or_else(|| invalid_membership(&path, format!("`{full_key}` must be an array of strings")))?;
275	        compile_globs(&path, &full_key, &entries).map(Some)
276	    };
277	    Ok(Membership {
278	        members: globs("members")?,
279	        exclude: globs("exclude")?.unwrap_or_else(NegatableGlobSet::empty),
280	        hybrid_root,
281	        declared: true,
282	    })
283	}
