293	/// The membership of each workspace nested below the workspace root, keyed by its directory (`None` where the directory
294	/// declares no workspace), and what has been learned about Cargo workspace manifests on the way.
295	#[derive(Default)]
296	pub(crate) struct NestedMemberships {
297	    cargo: HashMap<PathBuf, Membership>,
298	    reads: callisto_manifests::WorkspaceReads,
299	    npm: HashMap<PathBuf, Option<NpmMembership>>,
300	    python: HashMap<PathBuf, Option<Membership>>,
301	}
