340	/// The nearest directory above `rel`, below `root`, whose own manifest declares a workspace judges `rel` by its list,
341	/// with `rel` taken relative to it. With no such directory nothing nested has an opinion.
342	fn judged_by_nearest_declared_workspace<M>(
343	    root: &Path,
344	    rel: &Path,
345	    cache: &mut HashMap<PathBuf, Option<M>>,
346	    read: impl Fn(&Path) -> Result<Option<M>, LocateError>,
347	    admits: impl Fn(&M, &Path) -> bool,
348	) -> Result<bool, LocateError> {
349	    for ancestor in rel.ancestors().skip(1) {
350	        if ancestor.as_os_str().is_empty() || ancestor == Path::new(".") {
351	            break;
352	        }
353	        if !cache.contains_key(ancestor) {
354	            let membership = read(&root.join(ancestor))?;
355	            cache.insert(ancestor.to_path_buf(), membership);
356	        }
357	        if let Some(membership) = &cache[ancestor] {
358	            let within = rel.strip_prefix(ancestor).unwrap_or(rel);
359	            return Ok(admits(membership, within));
360	        }
361	    }
362	    Ok(true)
363	}
