365	/// Whether a Cargo workspace nested below `root` admits the package at `rel`. The workspace at `root` is judged by
366	/// [`read_cargo_membership`]; this adds the verdict of a nearer workspace that governs the package, which judges it by its
367	/// own `members` and `exclude`. A package that is itself a workspace root, or that no nested workspace governs, passes.
368	pub(crate) fn nested_cargo_workspace_admits(
369	    root: &Path,
370	    rel: &Path,
371	    manifest_text: &str,
372	    nested: &mut NestedMemberships,
373	) -> Result<bool, LocateError> {
374	    let manifest = rel.join("Cargo.toml");
375	    let located = |error: ManifestError| match error {
376	        ManifestError::Parse { path, message, .. } => parse_error(&root.join(path), message),
377	        ManifestError::Read { path, message } => LocateError::ManifestReadError {
378	            path: root.join(path),
379	            message,
380	        },
381	        other => LocateError::ManifestReadError {
382	            path: root.join(&manifest),
383	            message: other.to_string(),
384	        },
385	    };
386	    let document = callisto_manifests::parse_manifest(&manifest, manifest_text).map_err(located)?;
387	    let Some(governing) = nested
388	        .reads
389	        .enclosing(&manifest, &document, callisto_manifests::read_manifest_text(root))
390	        .map_err(located)?
391	    else {
392	        return Ok(true);
393	    };
394	    let governing_dir = governing.parent().unwrap_or(Path::new(""));
395	    // A workspace named by `package.workspace` from outside the package's own ancestry has no path to judge by.
396	    let Ok(within) = rel.strip_prefix(governing_dir) else {
397	        return Ok(true);
398	    };
399	    if governing_dir.as_os_str().is_empty() || within.as_os_str().is_empty() {
400	        return Ok(true);
401	    }
402	    if !nested.cargo.contains_key(governing_dir) {
403	        let membership = read_cargo_membership(&root.join(governing_dir))?;
404	        nested.cargo.insert(governing_dir.to_path_buf(), membership);
405	    }
406	    Ok(nested.cargo[governing_dir].admits(within, false))
407	}
