187	/// What reading a directory's canonical manifests found: those that parsed, and those that could not be read or parsed.
188	type DirectoryManifests = (
189	    Vec<(Ecosystem, String, callisto_manifests::ManifestIdentity)>,
190	    Vec<(PathBuf, ManifestFailure)>,
191	);
192	
193	/// Reads and parses every canonical manifest present in `path`, so a parse failure can later check whether a *sibling*
194	/// manifest in the directory was admitted, not only its own ecosystem's membership.
195	fn read_manifests(path: &Path) -> DirectoryManifests {
196	    let mut parsed = Vec::new();
197	    let mut failures = Vec::new();
198	    for ecosystem in Ecosystem::CANONICAL {
199	        // Every `Ecosystem::CANONICAL` member has a canonical manifest format by construction -- see its doc comment.
200	        let Some(format) = ecosystem.canonical_manifest_format() else {
201	            continue;
202	        };
203	        let manifest_path = path.join(format.file_name());
204	        let content = match callisto_model::strict_fs::read_optional(&manifest_path) {
205	            Ok(Some(content)) => content,
206	            Ok(None) => continue,
207	            Err(e) => {
208	                failures.push((manifest_path, ManifestFailure::Unreadable(e.to_string())));
209	                continue;
210	            }
211	        };
212	        match callisto_manifests::read_identity(format, &content, &manifest_path) {
213	            Ok(identity) => parsed.push((ecosystem, content, identity)),
214	            Err(e) => failures.push((manifest_path, ManifestFailure::Unparseable(e.to_string()))),
215	        }
216	    }
217	    (parsed, failures)
218	}
219	
220	/// Git cannot stage a path beneath a symbolic link, so a package there could be edited on disk but never committed.
221	/// Discovery follows links only so that it can name such a package here instead of silently skipping it.
222	fn reject_symlinked_package(root: &Path, rel: &Path) -> Result<(), LocateError> {
223	    let mut current = root.to_path_buf();
224	    for component in rel.components() {
225	        current.push(component);
226	        let metadata = std::fs::symlink_metadata(&current).map_err(|error| LocateError::Walk {
227	            path: current.clone(),
228	            message: error.to_string(),
229	        })?;
230	        if metadata.file_type().is_symlink() {
231	            return Err(LocateError::SymlinkedPackage {
232	                path: rel.to_path_buf(),
233	            });
234	        }
235	    }
236	    Ok(())
237	}
238	
239	/// Why a manifest present in a directory could not be turned into an identity.
240	enum ManifestFailure {
241	    Unreadable(String),
242	    Unparseable(String),
243	}
244	
245	/// Warning text for a manifest that fails to read or parse but isn't a workspace member (its own
246	/// ecosystem doesn't admit it, and it shares no directory with an admitted manifest) --
247	/// tested directly, since `eprintln!` output can't be captured from inside discovery.
248	fn unparseable_manifest_warning(path: &Path, failure: &ManifestFailure) -> String {
249	    match failure {
250	        ManifestFailure::Unreadable(message) => {
251	            format!("warning: failed to read manifest `{}`: {message}", path.display())
252	        }
253	        ManifestFailure::Unparseable(message) => {
254	            format!("warning: failed to parse manifest `{}`: {message}", path.display())
255	        }
256	    }
257	}
