259	fn to_workspace_relative(path: &Path, root: &Path) -> Result<PathBuf, LocateError> {
260	    if !path.starts_with(root) {
261	        return Err(LocateError::OutsideWorkspaceRoot {
262	            path: path.to_path_buf(),
263	            root: root.to_path_buf(),
264	        });
265	    }
266	    let rel = path
267	        .strip_prefix(root)
268	        .expect("the walk only yields paths under its root");
269	    if rel.as_os_str().is_empty() {
270	        Ok(PathBuf::from("."))
271	    } else {
272	        workspace_relative(rel).map_err(|_e| LocateError::OutsideWorkspaceRoot {
273	            path: path.to_path_buf(),
274	            root: root.to_path_buf(),
275	        })
276	    }
277	}
