use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use callisto_model::{workspace_relative, Ecosystem, PackageId, ProjectRoot};
use ignore::WalkBuilder;

use crate::parallel::map_in_parallel;

use crate::locate::membership;
use crate::locate::{find_workspace_root, LocateError, ProjectLocator};

pub struct IgnoreWalkLocator {
    root: PathBuf,
    skip: BTreeSet<&'static str>,
}

impl IgnoreWalkLocator {
    pub fn new(root: &Path) -> Self {
        let mut skip = BTreeSet::new();
        skip.insert("target");
        skip.insert("node_modules");
        skip.insert(".git");
        skip.insert(".moon");
        skip.insert("dist");

        let canonical = dunce::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
        IgnoreWalkLocator { root: canonical, skip }
    }

    pub fn discover(start: &Path, runner: &dyn callisto_model::CommandRunner) -> Result<Self, LocateError> {
        let root = find_workspace_root(start, runner)?;
        Ok(Self::new(&root))
    }
}

impl ProjectLocator for IgnoreWalkLocator {
    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError> {
        Ok(self.projects_and_platform_candidates()?.0)
    }

    fn projects_and_platform_candidates(&self) -> Result<(Vec<ProjectRoot>, Vec<ProjectRoot>), LocateError> {
        let mut results = Vec::new();
        let mut platform_candidates = Vec::new();
        let cargo_membership = membership::read_cargo_membership(&self.root)?;
        let npm_membership = membership::read_npm_membership(&self.root)?;
        let python_membership = membership::read_python_membership(&self.root)?;
        let mut nested = membership::NestedMemberships::default();
        let walker = WalkBuilder::new(&self.root)
            .hidden(true)
            .git_ignore(true)
            // A workspace root below the Git toplevel has no `.git` of its own, but its `.gitignore` must still apply.
            .require_git(false)
            .parents(false)
            .max_depth(Some(32))
            // Links are followed only so a package beneath one can be named and rejected; the depth cap bounds a cycle.
            .follow_links(true)
            .filter_entry({
                let skip = self.skip.clone();
                move |entry| {
                    if let Some(name) = entry.file_name().to_str()
                        && skip.contains(name)
                    {
                        return false;
                    }
                    true
                }
            })
            .build();

        let mut directories = Vec::new();
        for entry_res in walker {
            let entry = entry_res.map_err(|e| LocateError::Walk {
                path: self.root.clone(),
                message: e.to_string(),
            })?;
            if entry.path().is_dir() {
                directories.push(entry.into_path());
            }
        }

        // Reading and parsing the manifests is independent per directory, so it runs on several threads. Everything
        // that decides, reports or fails stays below, in walk order.
        let first_pass = map_in_parallel(&directories, |directory| read_manifests(directory));

        for (path, (parsed, failures)) in directories.iter().map(PathBuf::as_path).zip(first_pass) {
            let rel = to_workspace_relative(path, &self.root)?;
            let is_root = rel == Path::new(".");
            let admits = |ecosystem: Ecosystem| match ecosystem {
                Ecosystem::Cargo => cargo_membership.admits(&rel, is_root),
                Ecosystem::Npm => npm_membership.admits(&rel, is_root),
                Ecosystem::Pypi => python_membership.admits(&rel, is_root),
                _ => false,
            };
            // Own-path check for a *failed* manifest: only a real, explicit members/workspaces
            // match counts -- the admit-all fallback (no restriction present, e.g. because this
            // very manifest is the one that failed to parse) must not count as membership.
            let admits_explicitly = |ecosystem: Ecosystem| match ecosystem {
                Ecosystem::Cargo => cargo_membership.admits_explicitly(&rel, is_root),
                Ecosystem::Npm => npm_membership.admits_explicitly(&rel, is_root),
                Ecosystem::Pypi => python_membership.admits_explicitly(&rel, is_root),
                _ => false,
            };

            // Explicit only, like `self_admitted` below -- a sibling that's merely admitted by
            // the fallback admit-all (no restriction present for that ecosystem) doesn't make
            // this directory a real, deliberate workspace member; only a genuine members/
            // workspaces match does.
            let any_sibling_admitted = parsed
                .iter()
                .any(|(ecosystem, _, identity)| identity.name.is_some() && admits_explicitly(*ecosystem));

            for (manifest_path, failure) in failures {
                // Determine which ecosystem this failed manifest belongs to from its
                // file name, to check its own membership independent of any sibling.
                let ecosystem = Ecosystem::CANONICAL.into_iter().find(|eco| {
                    eco.canonical_manifest_format()
                        .is_some_and(|f| Some(f.file_name()) == manifest_path.file_name().and_then(|n| n.to_str()))
                });
                let self_admitted = ecosystem.is_some_and(admits_explicitly);
                if self_admitted || any_sibling_admitted {
                    return Err(match failure {
                        ManifestFailure::Unreadable(message) => LocateError::ManifestReadError {
                            path: manifest_path,
                            message,
                        },
                        ManifestFailure::Unparseable(message) => LocateError::ManifestParseError {
                            path: manifest_path,
                            message,
                        },
                    });
                }
                eprintln!("{}", unparseable_manifest_warning(&manifest_path, &failure));
            }

            for (ecosystem, content, identity) in parsed {
                let Some(name) = identity.name else {
                    continue;
                };

                // A private, versionless package.json that holds an npm workspace (the standard root layout,
                // e.g. `@changesets/cli`, or one below the root) declares a name only to hold `workspaces`; it
                // is never itself a released package, so it never becomes a project.
                if ecosystem == Ecosystem::Npm
                    && identity.version.is_none()
                    && callisto_manifests::npm_declares_private(&content)
                    && (is_root || membership::declares_npm_workspace(path)?)
                {
                    continue;
                }

                // A crate with no `version` (an xtask or other internal tool; Cargo reads it as 0.0.0 and cannot
                // publish it) has nothing to version or release, so it is not a package. One that inherits its
                // version from the workspace still is.
                if ecosystem == Ecosystem::Cargo && identity.version.is_none() {
                    eprintln!(
                        "note: skipping `{}`: it declares no version, so Callisto cannot version or release it",
                        rel.display()
                    );
                    continue;
                }

                let admitted = admits(ecosystem)
                    && (is_root
                        || membership::nested_workspace_admits(&self.root, &rel, ecosystem, &content, &mut nested)?);
                let id = PackageId::parse(&name).unwrap_or_else(|_| PackageId::Bare(name.clone()));
                let project = ProjectRoot {
                    id,
                    path: rel.clone(),
                    ecosystem,
                };
                if admitted {
                    reject_symlinked_package(&self.root, &rel)?;
                    results.push(project);
                } else if ecosystem == Ecosystem::Npm && callisto_manifests::npm_role_from_source(&content).is_some() {
                    reject_symlinked_package(&self.root, &rel)?;
                    platform_candidates.push(project);
                }
            }
        }

        results.sort_by(|a, b| (&a.path, a.ecosystem).cmp(&(&b.path, b.ecosystem)));
        platform_candidates.sort_by(|a, b| a.path.cmp(&b.path));
        Ok((results, platform_candidates))
    }
}

/// What reading a directory's canonical manifests found: those that parsed, and those that could not be read or parsed.
type DirectoryManifests = (
    Vec<(Ecosystem, String, callisto_manifests::ManifestIdentity)>,
    Vec<(PathBuf, ManifestFailure)>,
);

/// Reads and parses every canonical manifest present in `path`, so a parse failure can later check whether a *sibling*
/// manifest in the directory was admitted, not only its own ecosystem's membership.
fn read_manifests(path: &Path) -> DirectoryManifests {
    let mut parsed = Vec::new();
    let mut failures = Vec::new();
    for ecosystem in Ecosystem::CANONICAL {
        // Every `Ecosystem::CANONICAL` member has a canonical manifest format by construction -- see its doc comment.
        let Some(format) = ecosystem.canonical_manifest_format() else {
            continue;
        };
        let manifest_path = path.join(format.file_name());
        let content = match callisto_model::strict_fs::read_optional(&manifest_path) {
            Ok(Some(content)) => content,
            Ok(None) => continue,
            Err(e) => {
                failures.push((manifest_path, ManifestFailure::Unreadable(e.to_string())));
                continue;
            }
        };
        match callisto_manifests::read_identity(format, &content, &manifest_path) {
            Ok(identity) => parsed.push((ecosystem, content, identity)),
            Err(e) => failures.push((manifest_path, ManifestFailure::Unparseable(e.to_string()))),
        }
    }
    (parsed, failures)
}

/// Git cannot stage a path beneath a symbolic link, so a package there could be edited on disk but never committed.
/// Discovery follows links only so that it can name such a package here instead of silently skipping it.
fn reject_symlinked_package(root: &Path, rel: &Path) -> Result<(), LocateError> {
    let mut current = root.to_path_buf();
    for component in rel.components() {
        current.push(component);
        let metadata = std::fs::symlink_metadata(&current).map_err(|error| LocateError::Walk {
            path: current.clone(),
            message: error.to_string(),
        })?;
        if metadata.file_type().is_symlink() {
            return Err(LocateError::SymlinkedPackage {
                path: rel.to_path_buf(),
            });
        }
    }
    Ok(())
}

/// Why a manifest present in a directory could not be turned into an identity.
enum ManifestFailure {
    Unreadable(String),
    Unparseable(String),
}

/// Warning text for a manifest that fails to read or parse but isn't a workspace member (its own
/// ecosystem doesn't admit it, and it shares no directory with an admitted manifest) --
/// tested directly, since `eprintln!` output can't be captured from inside discovery.
fn unparseable_manifest_warning(path: &Path, failure: &ManifestFailure) -> String {
    match failure {
        ManifestFailure::Unreadable(message) => {
            format!("warning: failed to read manifest `{}`: {message}", path.display())
        }
        ManifestFailure::Unparseable(message) => {
            format!("warning: failed to parse manifest `{}`: {message}", path.display())
        }
    }
}

fn to_workspace_relative(path: &Path, root: &Path) -> Result<PathBuf, LocateError> {
    if !path.starts_with(root) {
        return Err(LocateError::OutsideWorkspaceRoot {
            path: path.to_path_buf(),
            root: root.to_path_buf(),
        });
    }
    let rel = path
        .strip_prefix(root)
        .expect("the walk only yields paths under its root");
    if rel.as_os_str().is_empty() {
        Ok(PathBuf::from("."))
    } else {
        workspace_relative(rel).map_err(|_e| LocateError::OutsideWorkspaceRoot {
            path: path.to_path_buf(),
            root: root.to_path_buf(),
        })
    }
}

