4	/// A glob pattern for matching package names in `[[package-set]]` blocks.
5	///
6	/// Unlike `[[package]]` which uses an exact `PackageId` match,
7	/// `[[package-set]]` allows a single rule to target many packages at once
8	/// via a glob (e.g. `"pkg-*"` matches `pkg-a`, `pkg-b`, etc.).
9	///
10	/// The ecosystem prefix is respected: `"cargo/pkg-*"` only matches Cargo packages. Config loading requires the
11	/// prefix; a bare pattern parses here but matches every ecosystem.
12	#[derive(Clone, Debug)]
13	pub struct PackagePattern {
14	    raw: String,
15	    /// The ecosystem parsed off the front of the pattern (e.g. `cargo` in
16	    /// `"cargo/pkg-*"`), or `None` for a bare pattern like `"pkg-*"`.
17	    ecosystem: Option<Ecosystem>,
18	    /// Compiled from the pattern with any `ecosystem/` prefix stripped.
19	    matcher: GlobMatcher,
20	}
21	
22	impl PackagePattern {
23	    pub fn parse(s: &str) -> Result<Self, globset::Error> {
24	        let (ecosystem, rest) = s
25	            .split_once('/')
26	            .and_then(|(prefix, rest)| Ecosystem::from_prefix(prefix).map(|eco| (Some(eco), rest)))
27	            .unwrap_or((None, s));
28	        let glob = Glob::new(rest)?;
29	        Ok(Self {
30	            raw: s.to_string(),
31	            ecosystem,
32	            matcher: glob.compile_matcher(),
33	        })
34	    }
35	
36	    /// Returns the ecosystem this pattern was scoped to via an
37	    /// `ecosystem/` prefix, or `None` for a bare pattern.
38	    pub fn ecosystem(&self) -> Option<Ecosystem> {
39	        self.ecosystem
40	    }
